// Package behavior holds the generic behavior engine's domain types and the
// store interfaces the engine depends on. Nothing here knows what a
// particular behavior does: behavior-specific words live only in behavior
// files.
package behavior

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"time"
)

// Credential names and kinds used by the engine. The Telegram webhook secret
// is generated by the CLI, stored encrypted through the secrets resolver and
// never printed.
const (
	CredentialTelegramWebhookSecret = "telegram_webhook_secret"
	CredentialKindTelegramWebhook   = "telegram_webhook"
)

// Store errors.
var (
	ErrNotFound     = errors.New("behavior: not found")
	ErrConflict     = errors.New("behavior: conflict")
	ErrNotPublished = errors.New("behavior: no published version")
	ErrDecided      = errors.New("behavior: approval already decided")
	ErrExpired      = errors.New("behavior: approval expired")
	ErrStaleClaim   = errors.New("behavior: stale claim")
	ErrInvalid      = errors.New("behavior: invalid value")
)

// Status is a behavior's lifecycle status.
type Status string

const (
	StatusDraft    Status = "draft"
	StatusEnabled  Status = "enabled"
	StatusDisabled Status = "disabled"
)

// RunStatus is a run's status.
type RunStatus string

const (
	RunPending  RunStatus = "pending"
	RunRunning  RunStatus = "running"
	RunDone     RunStatus = "done"
	RunFailed   RunStatus = "failed"
	RunCanceled RunStatus = "canceled"
	// RunSkipped: a pre-check on the subject did not hold (for example the
	// assignee or list a trigger asked for); no model work was done.
	RunSkipped RunStatus = "skipped"
)

// Class is the engine's decision for an item.
type Class string

const (
	ClassAuto   Class = "auto"
	ClassNotify Class = "notify"
	ClassAsk    Class = "ask"
)

// ItemStatus is an item's status.
type ItemStatus string

const (
	ItemDrafted  ItemStatus = "drafted"
	ItemDone     ItemStatus = "done"
	ItemAsked    ItemStatus = "asked"
	ItemAnswered ItemStatus = "answered"
	ItemExpired  ItemStatus = "expired"
	ItemSkipped  ItemStatus = "skipped"
	ItemConflict ItemStatus = "conflict"
	ItemFailed   ItemStatus = "failed"
)

// Rating is the owner's feedback on an item.
type Rating string

const (
	RatingUp   Rating = "up"
	RatingDown Rating = "down"
)

// ApprovalKind says what an approval decides.
type ApprovalKind string

const (
	ApprovalItemAnswer    ApprovalKind = "item_answer"
	ApprovalPostDraft     ApprovalKind = "post_draft"
	ApprovalConfirmAction ApprovalKind = "confirm_action"
	// ApprovalFeedback is the handle of the 👍/👎 buttons on a message that
	// decides nothing (a digest or FYI about one item).
	ApprovalFeedback ApprovalKind = "feedback"
	// ApprovalFeedbackReason waits for the owner's optional free-text reason
	// for a 👎.
	ApprovalFeedbackReason ApprovalKind = "feedback_reason"
)

// Decision is an approval's outcome.
type Decision string

const (
	DecisionApproved Decision = "approved"
	DecisionRejected Decision = "rejected"
	DecisionAnswered Decision = "answered"
	DecisionExpired  Decision = "expired"
)

// DigestMode controls when notify messages are sent.
type DigestMode string

const (
	DigestPerRun DigestMode = "per_run"
	DigestHourly DigestMode = "hourly"
	DigestDaily  DigestMode = "daily"
)

// DecisionSource says how a remembered decision was made.
type DecisionSource string

const (
	SourceAskAnswer  DecisionSource = "ask_answer"
	SourceAutoPosted DecisionSource = "auto_posted"
	SourceAutoUndone DecisionSource = "auto_undone"
)

// UpdateKind is the kind of a stored inbound Telegram update.
type UpdateKind string

const (
	UpdateCommand  UpdateKind = "command"
	UpdateCallback UpdateKind = "callback"
	UpdateText     UpdateKind = "text"
	UpdateOther    UpdateKind = "other"
)

// Note codes on an inbound update say why content was not kept.
const (
	NoteArgsTooLong = "args_too_long" // command arguments over 512 characters
	NoteTextTooLong = "text_too_long" // a free-text reply over 4000 characters
	NoteBadCommand  = "bad_command"   // text starting with "/" that is not a command name
	NoteNoOpenReply = "no_open_reply" // a reply to a message that waits for no answer
	NoteBadCallback = "bad_callback"  // callback data that is not engine data
)

// Behavior is a behavior and its current draft.
type Behavior struct {
	ID            int64
	Name          string
	Status        Status
	Draft         json.RawMessage // the parsed draft document (object)
	DraftVars     json.RawMessage // var values imported with the draft (object)
	DraftSource   string          // the imported text, for export
	LatestVersion int             // 0 when never published
	CreatedAt     time.Time
	UpdatedAt     time.Time
}

// Version is an immutable published version.
type Version struct {
	ID          int64
	BehaviorID  int64
	Name        string
	Version     int
	Document    json.RawMessage
	Vars        json.RawMessage
	Source      string
	PublishedAt time.Time
}

// Usage is a run's model usage and step count.
type Usage struct {
	InputTokens, OutputTokens, CacheReadTokens, CacheWriteTokens int
	Steps                                                        int
}

// NewRun asks for a run of one pinned version.
type NewRun struct {
	BehaviorID    int64
	VersionID     int64
	Version       int
	TriggerKind   string
	Trigger       json.RawMessage // trusted identifiers only
	Subject       string          // e.g. "<source>:<type>:<id>"
	Revision      string
	CorrelationID string // UUID; generated when empty
	RunAt         time.Time
}

// Run is one execution of a pinned behavior version.
type Run struct {
	ID            int64
	WorkspaceID   string
	BehaviorID    int64
	BehaviorName  string // set by trace reads
	VersionID     int64
	Version       int
	TriggerKind   string
	Trigger       json.RawMessage
	Subject       string
	Revision      string
	Status        RunStatus
	CorrelationID string
	Attempts      int
	ClaimToken    string // set only on a claimed run
	Usage         Usage
	ErrorCode     string
	Snapshot      json.RawMessage
	// Context is the context snapshot the model saw (see ContextSnapshot);
	// empty until the run collected its context.
	Context json.RawMessage
	// RunActions holds the outcomes of the run's run-level actions
	// (RunActionsResult); empty until the first one finished.
	RunActions json.RawMessage
	UndoneAt   *time.Time
	RunAt      time.Time
	StartedAt  *time.Time
	FinishedAt *time.Time
	CreatedAt  time.Time
	UpdatedAt  time.Time
}

// Citation points at a source fragment.
type Citation struct {
	Locator string `json:"locator"`
	Quote   string `json:"quote"`
}

// NewItem is a classified item to store.
type NewItem struct {
	RunID         int64
	Key           string
	Label         string
	Text          string
	Proposal      string
	Citations     []Citation
	Topic         string
	Confidence    float64
	Informational bool
	Flags         []string
	Class         Class
	Rule          string
	Status        ItemStatus
}

// Item is a stored run item.
type Item struct {
	ID            int64
	RunID         int64
	Key           string
	Label         string
	Text          string
	Proposal      string
	Citations     []Citation
	Topic         string
	Confidence    float64
	Informational bool
	Flags         []string
	Class         Class
	Rule          string
	Status        ItemStatus
	ActionResult  json.RawMessage
	Rating        Rating
	RatingReason  string
	RatedAt       *time.Time
	CreatedAt     time.Time
	UpdatedAt     time.Time
}

// NewApproval asks the owner for one decision.
type NewApproval struct {
	Kind      ApprovalKind
	RunID     int64 // 0 when none
	ItemID    int64 // 0 when none
	Action    string
	Resource  string
	Payload   json.RawMessage
	Options   json.RawMessage
	Nonce     string // 16..64 of [A-Za-z0-9_-]
	ExpiresAt time.Time
}

// Approval is a stored approval request and its decision.
type Approval struct {
	ID                int64
	WorkspaceID       string
	Kind              ApprovalKind
	RunID             int64
	ItemID            int64
	Action            string
	Resource          string
	Payload           json.RawMessage
	Options           json.RawMessage
	Nonce             string
	ExpiresAt         time.Time
	Decision          Decision // empty while open
	Answer            string
	DecidedBy         string
	DecidedAt         *time.Time
	TelegramMessageID int64
	// ReplyMessageID puts the approval in free-text mode: a Telegram reply
	// to this message is its answer. 0 when not in free-text mode.
	ReplyMessageID int64
	// PendingAnswer is a staged free-text reply not yet handed on.
	PendingAnswer string
	CreatedAt     time.Time
}

// InboundUpdate is a normalized Telegram update. Only a short command and
// its arguments are kept, never the full message text. For a callback,
// Command holds the callback data and Args the callback query ID and the
// message ID ("<query id> <message id>"); for a free-text reply, Args holds
// the nonce of the approval the reply was staged on.
type InboundUpdate struct {
	ID            int64
	WorkspaceID   string
	IntegrationID string // the Telegram integration (bot) it came through
	UpdateID      int64
	ChatID        int64
	Kind          UpdateKind
	Command       string // at most 64 characters
	Args          string // at most 512 characters
	Note          string // a short code (see Note*), never content
	Attempts      int
	ClaimToken    string
	ReceivedAt    time.Time
}

// Profile is the owner's personalization.
type Profile struct {
	Language     string
	Tone         string
	QuietStart   *int // minute of day, 0..1439; nil with QuietEnd when unset
	QuietEnd     *int
	Timezone     string
	DigestMode   DigestMode
	DefaultModel string // empty: the settings default
	Budgets      json.RawMessage
	UpdatedAt    time.Time
}

var (
	languageRe = regexp.MustCompile(`^[a-z]{2}(-[A-Z]{2})?$`)
	// claudeModelRe and opencodeModelRe are the two model id shapes (the
	// same as the settings package's): a Claude id, or an opencode
	// provider/model[#variant] id. Import accepts both; the run checks the
	// shape against the configured provider.
	claudeModelRe   = regexp.MustCompile(`^[a-z0-9][a-z0-9.-]{0,99}$`)
	opencodeModelRe = regexp.MustCompile(`^[a-z0-9][a-z0-9-]*/[A-Za-z0-9._-]+(#[A-Za-z0-9._-]+)?$`)
)

// validModelID reports whether m has either accepted model id shape.
func validModelID(m string) bool {
	return claudeModelRe.MatchString(m) || (len(m) <= 200 && opencodeModelRe.MatchString(m))
}

// DefaultProfile is the profile used before the owner sets one.
func DefaultProfile() Profile {
	return Profile{Language: "vi", Timezone: "Asia/Ho_Chi_Minh", DigestMode: DigestPerRun, Budgets: json.RawMessage(`{}`)}
}

// Validate checks every profile field.
func (p Profile) Validate() error {
	bad := func(field string) error { return fmt.Errorf("%w: profile %s", ErrInvalid, field) }
	if !languageRe.MatchString(p.Language) {
		return bad("language")
	}
	if len([]rune(p.Tone)) > 200 {
		return bad("tone")
	}
	if (p.QuietStart == nil) != (p.QuietEnd == nil) {
		return bad("quiet_hours")
	}
	for _, m := range []*int{p.QuietStart, p.QuietEnd} {
		if m != nil && (*m < 0 || *m > 1439) {
			return bad("quiet_hours")
		}
	}
	if p.Timezone == "" || len(p.Timezone) > 64 {
		return bad("timezone")
	}
	if _, err := time.LoadLocation(p.Timezone); err != nil {
		return bad("timezone")
	}
	switch p.DigestMode {
	case DigestPerRun, DigestHourly, DigestDaily:
	default:
		return bad("digest_mode")
	}
	if p.DefaultModel != "" && !validModelID(p.DefaultModel) {
		return bad("default_model")
	}
	if len(p.Budgets) > 0 {
		var obj map[string]json.RawMessage
		if json.Unmarshal(p.Budgets, &obj) != nil || obj == nil {
			return bad("budgets")
		}
	}
	return nil
}

// DecisionScope is where a remembered decision applies.
type DecisionScope struct {
	Behavior string `json:"behavior,omitempty"`
	List     string `json:"list,omitempty"`
	Repo     string `json:"repo,omitempty"`
}

// NewDecision is a decision to remember.
type NewDecision struct {
	Topic    string
	Question string
	Answer   string
	Scope    DecisionScope
	Source   DecisionSource
	RunID    int64 // 0 when none
	ItemID   int64 // 0 when none
}

// RememberedDecision is a stored decision.
type RememberedDecision struct {
	ID          int64
	Topic       string
	Question    string
	Answer      string
	Scope       DecisionScope
	Source      DecisionSource
	RunID       int64
	ItemID      int64
	Rank        float64 // set by search
	CreatedAt   time.Time
	ForgottenAt *time.Time
}

// Locator is the citation locator of a remembered decision.
func (d RememberedDecision) Locator() string { return fmt.Sprintf("memory:decision/%d", d.ID) }

// VersionStats counts the outcomes of one published version.
type VersionStats struct {
	Version                          int
	Runs, Undos                      int64
	FailedRuns, SkippedRuns          int64
	AutoItems, NotifyItems, AskItems int64
	Conflicts, RatedDown, RatedUp    int64
	// Items by status.
	DraftedItems, AskedItems, DoneItems, AnsweredItems int64
	ExpiredItems, SkippedItems, FailedItems            int64
	// Average model confidence of the items of each class (0 when none).
	AvgConfidenceAuto, AvgConfidenceNotify, AvgConfidenceAsk float64
}

// DefinitionStore persists behaviors and their versions.
type DefinitionStore interface {
	// SaveDraft creates the behavior or replaces its draft.
	SaveDraft(ctx context.Context, workspaceID, name string, draft, vars json.RawMessage, source string) (Behavior, error)
	GetBehavior(ctx context.Context, workspaceID, name string) (Behavior, error)
	ListBehaviors(ctx context.Context, workspaceID string) ([]Behavior, error)
	// Publish locks the behavior, runs check on the locked draft and, when
	// it passes, freezes the draft as the next version.
	Publish(ctx context.Context, workspaceID, name string, check func(Behavior) error) (Version, error)
	// SetStatus enables or disables a behavior; enabling needs a version.
	SetStatus(ctx context.Context, workspaceID, name string, status Status) error
	// GetVersion returns one version; version 0 is the latest.
	GetVersion(ctx context.Context, workspaceID, name string, version int) (Version, error)
	GetVersionByID(ctx context.Context, workspaceID string, id int64) (Version, error)
	ListVersions(ctx context.Context, workspaceID, name string) ([]Version, error)
	// EnabledVersions returns the latest version of each enabled behavior.
	EnabledVersions(ctx context.Context, workspaceID string) ([]Version, error)
	Stats(ctx context.Context, workspaceID, name string) ([]VersionStats, error)
}

// RunStore persists runs and their items.
type RunStore interface {
	// CreateRun stores a pending run once per (version, subject, revision);
	// a repeat returns the existing run and created=false.
	CreateRun(ctx context.Context, workspaceID string, r NewRun) (run Run, created bool, err error)
	// ClaimRun leases one due run, or returns nil. Runs whose lease ended
	// after maxAttempts are failed first.
	ClaimRun(ctx context.Context, now time.Time, lease time.Duration, maxAttempts int) (*Run, error)
	AddUsage(ctx context.Context, runID int64, claimToken string, u Usage) error
	FinishRun(ctx context.Context, runID int64, claimToken string, status RunStatus, errorCode string) error
	RetryRun(ctx context.Context, runID int64, claimToken string, next time.Time, errorCode string) error
	CancelPendingRun(ctx context.Context, workspaceID string, runID int64) error
	// SetSnapshot stores the undo snapshot once; false when one exists.
	SetSnapshot(ctx context.Context, workspaceID string, runID int64, snapshot json.RawMessage) (bool, error)
	// MarkUndone records an undo once; ErrConflict when already undone or
	// there is nothing to undo (no snapshot and no run-level outcomes).
	MarkUndone(ctx context.Context, workspaceID string, runID int64) error
	GetRun(ctx context.Context, workspaceID string, runID int64) (Run, error)
	LatestRunBySubject(ctx context.Context, workspaceID, subject string) (Run, error)

	// AddItem stores an item once per (run, key); a repeat returns the
	// stored item and created=false.
	AddItem(ctx context.Context, workspaceID string, it NewItem) (item Item, created bool, err error)
	GetItem(ctx context.Context, workspaceID string, itemID int64) (Item, error)
	GetItemByKey(ctx context.Context, workspaceID string, runID int64, key string) (Item, error)
	ListItems(ctx context.Context, workspaceID string, runID int64) ([]Item, error)
	// TransitionItem moves an item to `to` only from one of `from`;
	// ErrConflict otherwise. A nil result keeps the stored result.
	TransitionItem(ctx context.Context, workspaceID string, itemID int64, from []ItemStatus, to ItemStatus, result json.RawMessage) (Item, error)
	RateItem(ctx context.Context, workspaceID string, itemID int64, rating Rating, reason string) error
}

// ApprovalStore persists approvals.
type ApprovalStore interface {
	// CreateApproval fails with ErrConflict when the item already has an
	// open approval of the same kind or the nonce is taken.
	CreateApproval(ctx context.Context, workspaceID string, a NewApproval) (Approval, error)
	GetApproval(ctx context.Context, workspaceID string, id int64) (Approval, error)
	GetApprovalByNonce(ctx context.Context, workspaceID, nonce string) (Approval, error)
	// Decide takes the decision once, only while open and unexpired at now.
	// Otherwise: ErrNotFound, ErrDecided or ErrExpired.
	Decide(ctx context.Context, workspaceID, nonce string, d Decision, answer, actor string, now time.Time) (Approval, error)
	// ExpireDue marks up to limit overdue open approvals expired.
	ExpireDue(ctx context.Context, now time.Time, limit int) ([]Approval, error)
	SetApprovalMessage(ctx context.Context, workspaceID string, id, messageID int64) error
	// SetReplyMessage puts an open approval in free-text mode: a reply to
	// messageID becomes its answer. ErrNotFound when not open.
	SetReplyMessage(ctx context.Context, workspaceID string, id, messageID int64) error
	// StageAnswer stores a free-text reply on the newest open, unexpired
	// approval whose reply message is messageID and returns its nonce;
	// ErrNotFound when none waits for that message.
	StageAnswer(ctx context.Context, workspaceID string, messageID int64, answer string, now time.Time) (nonce string, err error)
	// ClearPendingAnswer drops a staged reply once it was handed on.
	ClearPendingAnswer(ctx context.Context, workspaceID string, id int64) error
	ListApprovals(ctx context.Context, workspaceID string, runID int64) ([]Approval, error)
}

// InboxStore persists inbound Telegram updates for dedupe and processing.
type InboxStore interface {
	// RecordUpdate stores an update once per update_id; false on a repeat.
	RecordUpdate(ctx context.Context, workspaceID string, u InboundUpdate) (bool, error)
	ClaimUpdate(ctx context.Context, now time.Time, lease time.Duration) (*InboundUpdate, error)
	FinishUpdate(ctx context.Context, id int64, claimToken, errorCode string) error
}

// ProfileStore persists the owner's profile.
type ProfileStore interface {
	// GetProfile returns DefaultProfile when none is stored.
	GetProfile(ctx context.Context, workspaceID string) (Profile, error)
	SaveProfile(ctx context.Context, workspaceID string, p Profile) (Profile, error)
}

// MemoryStore persists decision memory.
type MemoryStore interface {
	AddDecision(ctx context.Context, workspaceID string, d NewDecision) (RememberedDecision, error)
	GetDecision(ctx context.Context, workspaceID string, id int64) (RememberedDecision, error)
	// SearchDecisions matches any query word; an empty behavior matches
	// every scope.
	SearchDecisions(ctx context.Context, workspaceID, query, behavior string, limit int) ([]RememberedDecision, error)
	ListDecisions(ctx context.Context, workspaceID string, includeForgotten bool, limit, offset int) ([]RememberedDecision, error)
	// ForgetDecision hides a decision from search; ErrNotFound when unknown
	// or already forgotten.
	ForgetDecision(ctx context.Context, workspaceID string, id int64) error
}
